queries:
SELECT telescref
FROM signals
GROUP BY telescref
HAVING AVG(modindex) > (SELECT AVG(modindex) FROM signals WHERE modindex IS NOT NULL);
SELECT AVG(avg_mod) AS overall_avg_modindex
FROM (
  SELECT telescref, AVG(modindex) AS avg_mod
  FROM signals
  GROUP BY telescref
  HAVING COUNT(modindex) > 0
);
SELECT AVG(modindex) FROM signals;
